array.string:
until /usr/bin/curl -sf -o /dev/null http://localhost:8123/show/status; do sleep 1; done
LOG() { echo "$(date '+%Y-%m-%d %H:%M:%S') [kiosk] $*"; }
DISPLAY_INFO=$(swift - <<'SWIFTEOF'
import CoreGraphics
let mainID = CGMainDisplayID()
var count: UInt32 = 0
CGGetActiveDisplayList(0, nil, &count)
var ids = [CGDirectDisplayID](repeating: 0, count: Int(count))
CGGetActiveDisplayList(count, &ids, &count)
struct Disp { let id: CGDirectDisplayID; let bounds: CGRect; let isMain: Bool }
let displays = ids.map { Disp(id: $0, bounds: CGDisplayBounds($0), isMain: $0 == mainID) }
let externals = displays.filter { d in !d.isMain }
func area(_ r: CGRect) -> CGFloat { r.width * r.height }
let chosen: Disp
let reason: String
if externals.count == 1 {
    chosen = externals[0]
    reason = "1 external display found (id=\(chosen.id)); using it"
} else if externals.count > 1 {
    chosen = externals.max(by: { a, b in area(a.bounds) < area(b.bounds) })!
    reason = "\(externals.count) external displays found; using largest (id=\(chosen.id), \(Int(chosen.bounds.width))x\(Int(chosen.bounds.height)))"
} else {
    chosen = displays.first(where: { d in d.isMain })!
    reason = "no external display found; falling back to main display (id=\(chosen.id))"
}
let b = chosen.bounds
print("WINDOW_POSITION=\(Int(b.origin.x)),\(Int(b.origin.y))")
print("WINDOW_SIZE=\(Int(b.width)),\(Int(b.height))")
print("DECISION=\(reason) bounds=\(b)")
SWIFTEOF
)
WINDOW_POS=$(printf '%s\n' "$DISPLAY_INFO" | grep '^WINDOW_POSITION=' | cut -d= -f2)
WINDOW_SIZE=$(printf '%s\n' "$DISPLAY_INFO" | grep '^WINDOW_SIZE=' | cut -d= -f2)
DECISION=$(printf '%s\n' "$DISPLAY_INFO" | grep '^DECISION=' | cut -d= -f2-)
if [ -n "$WINDOW_POS" ] && [ -n "$WINDOW_SIZE" ]; then
    LOG "display picker: $DECISION"
    POS_ARGS="--window-position=$WINDOW_POS --window-size=$WINDOW_SIZE"
else
    LOG "display picker produced no usable output (raw: $DISPLAY_INFO); launching without explicit window position"
    POS_ARGS=""
fi
PROFILE_DIR="$HOME/Library/Application Support/arche-kiosk/Default"
mkdir -p "$PROFILE_DIR"
PREFS_FILE="$PROFILE_DIR/Preferences"
python3 - "$PREFS_FILE" <<'PYEOF'
import json, sys
path = sys.argv[1]
try:
    with open(path) as f:
        data = json.load(f)
except (FileNotFoundError, ValueError):
    data = {}
if not isinstance(data, dict):
    data = {}
browser = data.get("browser")
if not isinstance(browser, dict):
    browser = {}
browser["show_fullscreen_toolbar"] = False
data["browser"] = browser
with open(path, "w") as f:
    json.dump(data, f)
PYEOF
LOG "fullscreen-toolbar pref merged into $PREFS_FILE"
"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" --start-fullscreen $POS_ARGS --mute-audio --autoplay-policy=no-user-gesture-required --no-first-run --no-default-browser-check --disable-session-crashed-bubble --hide-crash-restore-bubble --disable-features=Translate,MediaRouter --user-data-dir="$HOME/Library/Application Support/arche-kiosk" "http://localhost:8123/demos.html?show=1#TEST_CARD" &
CHROME=$!
sleep 5
/usr/bin/osascript -e 'tell application "Google Chrome" to activate' >/dev/null 2>&1 || true
wait $CHROME
